CREATE TABLE IF NOT EXISTS hm_activation_code (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT NOT NULL,
  status INTEGER NOT NULL DEFAULT 0,
  card_type TEXT NOT NULL DEFAULT 'MONTH',
  valid_days INTEGER NOT NULL DEFAULT 30,
  device_id TEXT,
  device_name TEXT,
  platform TEXT,
  app_version TEXT,
  package_name TEXT,
  activated_at TEXT,
  expires_at TEXT,
  remark TEXT,
  issue_device_id TEXT,
  issue_ip TEXT,
  issue_at TEXT,
  create_time TEXT DEFAULT CURRENT_TIMESTAMP,
  update_time TEXT DEFAULT CURRENT_TIMESTAMP,
  create_by INTEGER,
  update_by INTEGER,
  deleted INTEGER DEFAULT 0,
  UNIQUE (code)
);

CREATE INDEX IF NOT EXISTS idx_hm_activation_device ON hm_activation_code (device_id);
CREATE INDEX IF NOT EXISTS idx_hm_activation_status ON hm_activation_code (status);
CREATE INDEX IF NOT EXISTS idx_hm_activation_card_type ON hm_activation_code (card_type);
CREATE INDEX IF NOT EXISTS idx_hm_activation_issue_device ON hm_activation_code (issue_device_id);
CREATE INDEX IF NOT EXISTS idx_hm_activation_issue_ip ON hm_activation_code (issue_ip);






























